mapper.select:
SELECT COUNT(*)
  FROM dcr04_emp_auth
 WHERE dcr04_person_id     = #{personId}
   AND dcr04_class_tree_id = #{classTreeId}

mapper.update:
UPDATE dcr04_emp_auth
   SET dcr04_note = #{note}
 WHERE dcr04_class_tree_id = #{classTreeId}
   AND dcr04_person_id     = #{personId}

mapper.delete:
DELETE FROM dcr04_emp_auth a
 USING dcr01_class_tree b
 WHERE b.dcr01_class_tree_id = a.dcr04_class_tree_id
   AND b.dcr01_company_id    = #{companyId}
   AND a.dcr04_emp_auth_id IN
#{id}
